BEGIN;
ALTER TABLE coach.alerts ADD COLUMN IF NOT EXISTS kind text, ADD COLUMN IF NOT EXISTS severity text;
ALTER TABLE coach.alerts ADD CONSTRAINT alerts_kind_ck CHECK (kind IS NULL OR kind IN ('checkin_overdue','inactivity','adherence_low','progress_stagnation','engagement_low'));
ALTER TABLE coach.alerts ADD CONSTRAINT alerts_severity_ck CHECK (severity IS NULL OR severity IN ('info','low','medium','high','critical'));
CREATE TABLE coach.alert_settings (coach_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, activity_threshold_days integer NOT NULL DEFAULT 3 CHECK(activity_threshold_days>0), adherence_threshold_pct integer NOT NULL DEFAULT 50 CHECK(adherence_threshold_pct BETWEEN 0 AND 100), engagement_threshold_days integer NOT NULL DEFAULT 7 CHECK(engagement_threshold_days>0), notify_activity boolean NOT NULL DEFAULT true, notify_adherence boolean NOT NULL DEFAULT true, notify_progress boolean NOT NULL DEFAULT true, notify_engagement boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE coach.alert_settings ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE ON coach.alert_settings TO authenticated; GRANT ALL ON coach.alert_settings TO service_role;
CREATE POLICY alert_settings_select ON coach.alert_settings FOR SELECT TO authenticated USING ((SELECT auth.uid())=coach_id);
CREATE POLICY alert_settings_insert ON coach.alert_settings FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid())=coach_id);
CREATE POLICY alert_settings_update ON coach.alert_settings FOR UPDATE TO authenticated USING ((SELECT auth.uid())=coach_id) WITH CHECK ((SELECT auth.uid())=coach_id);
CREATE POLICY alert_settings_delete ON coach.alert_settings FOR DELETE TO authenticated USING ((SELECT auth.uid())=coach_id);
CREATE OR REPLACE FUNCTION coach.raise_alert(p_client uuid,p_kind text,p_severity text,p_title text,p_detail text,p_metric jsonb DEFAULT '{}'::jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ DECLARE v_coach uuid:=nullif(current_setting('request.jwt.claim.sub',true),'')::uuid; v_id uuid; BEGIN IF v_coach IS NULL OR NOT EXISTS(SELECT 1 FROM coach.relationships WHERE coach_id=v_coach AND client_id=p_client AND status='active') THEN RAISE EXCEPTION 'active own relationship required' USING ERRCODE='42501'; END IF; IF p_kind NOT IN ('checkin_overdue','inactivity','adherence_low','progress_stagnation','engagement_low') THEN RAISE EXCEPTION 'medical or unknown alert kinds are not generated' USING ERRCODE='23514'; END IF; IF p_severity NOT IN ('info','low','medium','high','critical') OR jsonb_typeof(p_metric)<>'object' THEN RAISE EXCEPTION 'invalid factual alert' USING ERRCODE='23514'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(v_coach::text||p_client::text||p_kind,0)); SELECT id INTO v_id FROM coach.alerts WHERE coach_id=v_coach AND client_id=p_client AND kind=p_kind AND created_at>=now()-interval '24 hours' AND status<>'done' ORDER BY created_at DESC LIMIT 1; IF v_id IS NOT NULL THEN RETURN v_id; END IF; INSERT INTO coach.alerts(coach_id,client_id,module,kind,severity,title,detail,metric,created_by) VALUES(v_coach,p_client,'general',p_kind,p_severity,p_title,p_detail,p_metric,v_coach) RETURNING id INTO v_id; RETURN v_id; END $$;
REVOKE ALL ON FUNCTION coach.raise_alert(uuid,text,text,text,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION coach.raise_alert(uuid,text,text,text,text,jsonb) TO authenticated,service_role;
COMMENT ON FUNCTION coach.raise_alert(uuid,text,text,text,text,jsonb) IS 'C-459: faktischer Coach-Alarm mit 24h-Deduplizierung; keine Medical/Safety-Bewertung (E-74).';
COMMIT;
